            return String::new();
        }

        let mut ids = Vec::new();
        let max_line = (last_changed as usize).min(self.previous_lines.len().saturating_sub(1));
        for i in first_changed as usize..=max_line {
            for id in extract_kitty_image_ids(self.previous_lines.get(i).map_or("", String::as_str))
